window.__saqPaperQuestions("2018-2-metro-north",[{"number":1,"title":"","stemText":"(Total 18 marks) You are the Emergency Consultant on call overnight and you receive a phone-call from your ED registrar. There is a 2 year-old boy with severe croup who has been brought in by his parents. Your registrar is concerned that the boy requires intubation. Anaesthetics are not on site overnight. List 4 differentials for stridor in the paediatric population (other than croup): (4 marks)","parts":[{"id":"a","label":"Part A","prompt":"State 3 indications for intubation in this scenario.\n(3 marks)"},{"id":"b","label":"Part B","prompt":"What interventions can be used to support this child while preparing for intubation? List three (3) (3 marks)"},{"id":"c","label":"Part C","prompt":"What equipment and drugs will you select for intubation? (6 marks)"},{"id":"d","label":"Part D","prompt":"Give 4 anatomical airway differences in the paediatric population in comparison with the\nadult airway: (2 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>13/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bacterial tracheitis</div><div class=\"answer-line\">Epiglottitis</div><div class=\"answer-line\">Retropharyngeal abscess</div><div class=\"answer-line\">Laryngeal FB</div><div class=\"answer-line\">Angioneurotic oedema</div><div class=\"answer-line\">Subglottic haemangioma</div><div class=\"answer-line\">Laryngomalacia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Exhaustion from increased work of breathing</div><div class=\"answer-line\">Hypercapnoeic (type II) respiratory failure</div><div class=\"answer-line\">Hypoxaemic (type I) respiratory failure</div><div class=\"answer-line\">Decreased level of consciousness and unable to protect airway</div><div class=\"answer-line\">Imminent complete airway obstruction</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Keep pt calm and upright for as long as possible</div><div class=\"answer-line\">Optimise medical management – Adrenaline neb 5mg, Dexamethasone 0.3mg/kg PO/IV</div><div class=\"answer-line\">High-flow oxygen (potentially 2L/kg) via nasal prongs</div><div class=\"answer-line\">IV access (may delay until last minute)</div><div class=\"answer-line\">Explanation to, and/or involvement of parent</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Bag Valve Mask (with size - child)</div><div class=\"answer-line\">Laryngoscope with Miller blade (size 2) and Macintosh blade (size 2)<strong> </strong></div><div class=\"answer-line\">ETT 4.0-4.5 and one size <em>below</em> due to anticipated laryngeal oedema</div><div class=\"answer-line\">Bougie</div><div class=\"answer-line\">Suction</div><div class=\"answer-line\">Laryngeal Mask Airway (size 2)</div><div class=\"answer-line\">Surgical airway equipment – needle cricothyrotomy</div><div class=\"answer-line\">Ketamine 2mg/kg or Fentanyl 2-5 mcg/kg or Propofol 1-2 mg/kg</div><div class=\"answer-line\">Suxamethonium 1-2 mg/kg or Rocuronium 1.2 mg/kg<strong> </strong></div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospital      The Royal Brisbane &amp;Women Hospital           Redcliffe  and Caboolture                  Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong>                Emergency Department                            Emergency Departments                  Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div><div class=\"answer-line\"><strong>5.</strong><strong> </strong><strong>Give 4 anatomical airway differences  in paediatric population in comparison with adult </strong></div><div class=\"answer-line\"><strong>airway:  </strong></div><div class=\"answer-line\"><strong>(2 Marks) </strong></div><div class=\"answer-line\">Larger tongue</div><div class=\"answer-line\">Larynx more cephalic</div><div class=\"answer-line\">Increase compliance of chest wall</div><div class=\"answer-line\">Bulging occipital process (Flexed neck)</div><div class=\"answer-line\">Smaller mandible</div><div class=\"answer-line\">Narrowest part at cricoid cartilage</div><div class=\"answer-line\">Smaller diameter at airway, therefore, higher resistance to airflow.</div><div class=\"answer-line\">Pass mark: 13/18</div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"(Total 12 Marks) You are a new FACEM and your director has asked you to look into access block and overcrowding in your emergency department. Questions:","parts":[{"id":"a","label":"Part A","prompt":"State the definition of access block. (2 marks)"},{"id":"b","label":"Part B","prompt":"State the difference between access block and ED overcrowding. (2 marks)"},{"id":"c","label":"Part C","prompt":"List 4 markers of ED overcrowding.\n(4 marks)"},{"id":"d","label":"Part D","prompt":"List 4 adverse effects of ED overcrowding."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">An admitted patient who remains in the emergency department for &gt; 8 hours because of a delay in</div><div class=\"answer-line\">accessing an inpatient bed</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">ED overcrowding refers to the situation where ED function is impeded primarily because the number</div><div class=\"answer-line\">of patients waiting to be seen, undergoing assessment and treatment or waiting departure exceeds</div><div class=\"answer-line\">either the physical bed and or staffing capacity of the ED.  Access block is the principal cause of ED</div><div class=\"answer-line\">overcrowding.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Answer:</td></tr><tr><td>•</td><td>Inability to offload ambulance patients and a resultant loss of capacity in the local emergency</td></tr><tr><td colspan=\"2\">response in the community</td></tr><tr><td>•</td><td>Inability to place critically unwell patients in an appropriate treatment space when required</td></tr><tr><td>•</td><td>Patients undergoing clinical management in a non-treatment area, where privacy and access</td></tr><tr><td colspan=\"2\">to basic clinical resources is reduced or delayed</td></tr><tr><td>•</td><td>Admitted patients receiving a lower standard of care than they would receive in their</td></tr><tr><td colspan=\"2\">destination unit</td></tr><tr><td>•</td><td>Obstruction to access and egress routes from the ED in contravention of OH&amp;S requirements</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">1. Increased adverse events</div><div class=\"answer-line\">2. Increased violent behavior</div><div class=\"answer-line\">3. Increased errors</div><div class=\"answer-line\">4. Delayed time to critical care</div><div class=\"answer-line\">5. Increased morbidity</div><div class=\"answer-line\">6. Excess deaths</div><div class=\"answer-line\">Passmark: 7/12</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"(Total 12 marks) A 21-year-old male presents to a tertiary Emergency Department after suffering an injury to his right eye at work while hammering metal. His eye photo is included in the props booklet: Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities on the image\n(3 marks)"},{"id":"b","label":"Part B","prompt":"List 2 relevant negative findings\n(2 mark)"},{"id":"c","label":"Part C","prompt":"State what further investigation you would perform and justify your choice. (2 marks) ."},{"id":"d","label":"Part D","prompt":"State 5 immediate management steps.\n(5 marks)"}],"propPages":["asset:img0aefe054f910ef0843"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">. Lacerated sclera</div><div class=\"answer-line\">- <strong>Uveal prolapse</strong></div><div class=\"answer-line\">- <strong>Misshapen pupil </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">- No hyphema</div><div class=\"answer-line\">- No signs of extraoccular trauma</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Safe modality (CT/USS) to locate FB.</div><div class=\"answer-line\">-</div><div class=\"answer-line\">MRI incorrect and contraindicated.</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Plain film not appropriate as investigation in a tertiary ED.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">- Immediate opthalmological referral</div><div class=\"answer-line\">- Elevate head of the bed</div><div class=\"answer-line\">- Eye shield</div><div class=\"answer-line\">- ADT</div><div class=\"answer-line\">- IV antibiotics. (broad spectrum IV Pip taz or similar broad spectrum cover with appropriate dose)</div><div class=\"answer-line\">- Analgesia (IV with appropriate dose opiate)</div><div class=\"answer-line\">- Antiemetics (IV appropriate dose)</div><div class=\"answer-line\">Pass mark: 8/12</div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"(Total 12 Marks) A 5-day old neonate is brought in to ED by his mother after being discharged from hospital following a normal vaginal delivery. His mother reports poor feeding for the last few hours and she has noticed an increasing yellow discoloration of his skin:\nHis vital signs are:\n\nHR\n160\n\nRR\nCRT 2 -3 sec AVPU The child is jaundiced. Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 5 likely causes for his jaundice\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List 4 red flags during history and examination that warrant admission to the hospital.\n(4 marks)"},{"id":"c","label":"Part C","prompt":"List 3 investigations required in ED and provide a rationale for each one justify each one of them. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">3/5</div><div class=\"answer-line\"> Physiological (day 2-3)</div><div class=\"answer-line\"> Breastmilk jaundice</div><div class=\"answer-line\"> Sepsis</div><div class=\"answer-line\"> Haemolysis</div><div class=\"answer-line\"> TORCH infections</div><div class=\"answer-line\"> Biliary atresia</div><div class=\"answer-line\"> Hypothyroidism</div><div class=\"answer-line\"> G6PD</div><div class=\"answer-line\"> Metabolic disease / storage diseases</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">2/4</div><div class=\"answer-line\"> Prematurity</div><div class=\"answer-line\"> Low birth weight or small for gestation</div><div class=\"answer-line\"> Previous baby with significant jaundice or kernicterus</div><div class=\"answer-line\"> Unwell infant</div><div class=\"answer-line\"> Signs of kernicterus</div><div class=\"answer-line\"> Parental concerns</div><div class=\"answer-line\"> Onset from birth</div><div class=\"answer-line\"> Too high (Bili &gt;200 mmol/L) – bilirubin measured above the treatment nomogram</div><div class=\"answer-line\"> Conjugated bili &gt;25%</div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospital      The Royal Brisbane &amp;Women Hospital           Redcliffe  and Caboolture                  Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong>                Emergency Department                            Emergency Departments                  Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>2/3 marks</td><td>This is an easy wuestion – they must provide a reasonable rationale to get the full mark</td></tr><tr><td> FBC (and film) – hemolysis – Hb- smear – spherocytosis – reticulocyte count – for</td><td>hemolysis</td></tr><tr><td> ELFT’s – liver function and biliary obstruction</td><td> BC, Urine, LP – sepsis screen</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"(Total 12 Marks) A mother brings in her 2-year old son who she suspects may have swallowed a button battery some time over the last hour whilst visiting at a friend’s house. The child had been playing on the carpet when the mother suddenly noticed he had dismantled a small alarm clock and the battery was nowhere to be found. The boy looks well and is happy playing in the assessment cubicle.","parts":[{"id":"a","label":"Part A","prompt":"List your immediate management steps (4 marks)."},{"id":"b","label":"Part B","prompt":"Name two indications for immediate endoscopy and battery removal (2 marks). After assessing the patient, you determine that there are no indications for immediate endoscopic removal. You consider managing the patient conservatively at home."},{"id":"c","label":"Part C","prompt":"Name three other conditions required for conservative management of button battery ingestion (3 marks)."},{"id":"d","label":"Part D","prompt":"State three specific instructions you would give as part of your discharge advice (3 marks)."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Keep Nil by mouth</div><div class=\"answer-line\">X-ray neck AP and lateral  + chest + abdomen to confirm presence or</div><div class=\"answer-line\">absence of battery</div><div class=\"answer-line\">Obtain further history to determine whether single or multiple batteries /</div><div class=\"answer-line\">magnet co-ingestion</div><div class=\"answer-line\">Assess patient for any signs of complications from battery ingestion</div><div class=\"answer-line\">such as airway compromise, haematemesis, abdominal discomfort.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Battery lodged in oesophagus</div><div class=\"answer-line\">Symptomatic patient</div><div class=\"answer-line\">Magnet co-ingested</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Small battery ≤ 12 mm</div><div class=\"answer-line\">Only one battery ingested</div><div class=\"answer-line\">No pre-existing oesophageal disease</div><div class=\"answer-line\">Patient or caregiver is reliable, mentally competent</div><div class=\"answer-line\">Able to seek evaluation promptly if symptoms develop</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Seek immediate attention if any symptoms of bowel obstruction or GI</div><div class=\"answer-line\">bleed</div><div class=\"answer-line\">Regular diet, encourage activity</div><div class=\"answer-line\">Avoid laxatives</div><div class=\"answer-line\">Examine the stools to confirm battery passage</div><div class=\"answer-line\">Return for xray if not passed in 10-14 days</div><div class=\"answer-line\">Source: button battery ingestion treatment guideline www.poison.org</div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"(Total 12 Marks) A 36-year-old male electrician is brought into your ED post electrocution from exposure to a 11,000-volt power line. He was thrown against a metal panel 8 metres away and noted to have no signs of life on scene. Bystander CPR and ambulance resuscitation managed to gain ROSC after a down time of approximately 20 minutes. His initial cardiac rhythm on scene was ventricular fibrillation. On arrival to your ED this patient is intubated and ventilated with the following vital signs:\nHeart rate 84bpm\nBlood Pressure 145/90\nResp Rate 15 breath per min, hand ventilated\nO2 Sats 98% on 15L via BVM Questions:","parts":[{"id":"a","label":"Part A","prompt":"Name four factors related to the nature of electrical exposure that can influence the severity of an electrical injury. (4 Marks) Factor Influencing Injury Severity"},{"id":"b","label":"Part B","prompt":"List four types of injuries that can be sustained in this patient and provide an example of each type. Injury Type Example"},{"id":"c","label":"Part C","prompt":"List 4 indications for the use of telemetry in the Emergency Department for a patient with a suspected electrical injury, without cardiac arrest. (4 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Voltage level:</td><td>High voltage &gt; 1000 Volts are high risk injuries</td></tr><tr><td>Current level :</td><td>&gt;2 amps causes burns and &gt; 10 amps causes asystole</td></tr><tr><td>Current type:</td><td>AC more likely to precipitate VF compared with DC</td></tr><tr><td colspan=\"2\">AC is considered 3x more dangerous than DC due to its ability to cause tetanic</td></tr><tr><td colspan=\"2\">muscle contractions that prolongs contact of victim with the source.</td></tr><tr><td>Pathway of current:</td><td>Pathway determines type and severity of injury</td></tr><tr><td colspan=\"2\">Vertical pathway most dangerous as all organs are in the line of injury</td></tr><tr><td colspan=\"2\">Horizontal pathways usually spares brain but can still be fatal due to heart,</td></tr><tr><td colspan=\"2\">respiratory muscle and spinal cord involvemtn</td></tr><tr><td>Duration of current:</td><td>Longer the duration likely the more severe the injury</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">(This is an easy question, so both type <em>and</em> example are needed to gain a mark)</div><div class=\"answer-line\">Thermal Burns</div><div class=\"answer-line\">Burns to skin: varying thickness</div><div class=\"answer-line\">Burns to eyes</div><div class=\"answer-line\">Compartment syndrome</div><div class=\"answer-line\">Blast Trauma</div><div class=\"answer-line\">Blunt trauma to head / spinal / chest / abdomen from the blast</div><div class=\"answer-line\">Head Trauma</div><div class=\"answer-line\">Spinal Trauma</div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospital      The Royal Brisbane &amp;Women Hospital           Redcliffe  and Caboolture                  Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong>                Emergency Department                            Emergency Departments                  Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div><div class=\"answer-line\">Chest Trauma: Heaemothorax, Pneumothorax, Rib Fractures, Lung Contusions, Cardiac Contusions</div><div class=\"answer-line\">Abdominal / PelvicTrauma: Any type of visceral injuries</div><div class=\"answer-line\">Bony Injury: Any type of significant bony injury from the impact of the blast and being thrown.</div><div class=\"answer-line\">Tympanic Membrane rupture</div><div class=\"answer-line\">Cardiovascular Injury</div><div class=\"answer-line\">Cardiac dysrhythmias: Malignant (VF, Systole) to other conduction disorders</div><div class=\"answer-line\">Direct myocardial necrosis in high voltage or alternate currents.</div><div class=\"answer-line\">Neurological Injury</div><div class=\"answer-line\">Hypoxic brain from cardiac arrest</div><div class=\"answer-line\">Cotinuous tetanic contractions</div><div class=\"answer-line\">Seizures</div><div class=\"answer-line\">Spinal cord injuries</div><div class=\"answer-line\">Crush Injury / Acute renal failure / Rhabdomyolysis from ischaemia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">High voltage injury (&gt;1000 volts)</div><div class=\"answer-line\">Loss of consciousness</div><div class=\"answer-line\">Seizures</div><div class=\"answer-line\">ECG changes or documented arrhythmias</div><div class=\"answer-line\">Previous cardiac disease (especially cardiac arrhythmias)</div><div class=\"answer-line\">Burns</div><div class=\"answer-line\">Pass Mark is 9/12</div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"(Total 12 Marks) An elderly female is referred to your Emergency Department by her GP for review of new onset Atrial Fibrillation:\n\nObservations:\n\nGCS\n15/15\n\nBP\n110/60\n\nSat\n95% on RA\n\nRR\n18 per min","parts":[{"id":"a","label":"Part A","prompt":"List 4 potential causes for Atrial fibrillation.\n(4 Marks) Your registrar asks you whether to aim for rhythm or rate control ."},{"id":"b","label":"Part B","prompt":"List 2 factors which would make you consider rhythm control in this lady and 2\nfactors which would make you consider rate control (4 Marks) Rhythm Control Factors Rate Control Factors"},{"id":"c","label":"Part C","prompt":"Your registrar asks you whether she needs to be anticoagulated.\nList 4 factors you would consider for the above decision."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Coronary artery disease</div><div class=\"answer-line\">2. Hypertension</div><div class=\"answer-line\">3. Rheumatic valvular heart disease</div><div class=\"answer-line\">4. Thyrotoxicosis</div><div class=\"answer-line\">5. COPD</div><div class=\"answer-line\">6. Pericarditis</div><div class=\"answer-line\">7. Pulmonary emboli</div><div class=\"answer-line\">8. Electrolyte abnormalities (eg hypokalaemia/hypomagnesaemia)</div><div class=\"answer-line\">9. Pericarditis</div><div class=\"answer-line\">10. Cardiomyopathies</div><div class=\"answer-line\">11. Pre-excitation syndromes</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Reversible cause</div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospital      The Royal Brisbane &amp;Women Hospital           Redcliffe  and Caboolture                  Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong>                Emergency Department                            Emergency Departments                  Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div><div class=\"answer-line\"><strong>Rate control </strong></div><div class=\"answer-line\">(No mortality difference)</div><div class=\"answer-line\">Asymptomatic or minimal symptoms</div><div class=\"answer-line\">Duration greater than 48 hours</div><div class=\"answer-line\">Non- reversible cause</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Age greater than 65/75</div><div class=\"answer-line\">Female</div><div class=\"answer-line\">Congestive heart failure</div><div class=\"answer-line\">Previous stroke / TIA /thromboembolism</div><div class=\"answer-line\">Hypertension</div><div class=\"answer-line\">Diabetes mellitus</div><div class=\"answer-line\">Vascular disease</div><div class=\"answer-line\"><strong>Risks of anticoagulation </strong></div><div class=\"answer-line\">Falls</div><div class=\"answer-line\">Previous bleeds GIT / ICH</div><div class=\"answer-line\">Renal failure if using novel anticoagulants</div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"(Total 12 Marks) A 41-year-old male returns from a business trip and a few days later develops a painful left knee. He is finding it very difficult to walk due to pain. This is his first episode of joint problems. He is systemically well, there is no history of trauma and no\n• ther symptoms.\nHe is afebrile, with normal vital signs. A clinical photo of his knee is included in the props booklet:","parts":[{"id":"a","label":"Part A","prompt":"Describe the photo. (2 Mark)"},{"id":"b","label":"Part B","prompt":"List 4 differential diagnoses for the above presentation.\n(4 Marks)"},{"id":"c","label":"Part C","prompt":"Under an aseptic approach, an USS guided joint aspirate is taken. Complete the following table with the expected pathology findings. (4 Marks) Analysis of synovial fluid"},{"id":"d","label":"Part D","prompt":"The synovial fluid result suggests septic arthritis. What antibiotics do you give while awaiting culture results? (2 Mark)"}],"propPages":["asset:img549c6fa6a18e937366"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Unilateral erythematous swollen knee joint. N</div><div class=\"answer-line\">o visible wounds, no rash.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">a. Septic joint</div><div class=\"answer-line\">b. Gout</div><div class=\"answer-line\">c. Gonococcal arthritis</div><div class=\"answer-line\">d. Auto-immune arthritis</div><div class=\"answer-line\">e. Haemarthrosis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">One mark for each column completed ie appearance, WCC and %PMN</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">If penicillin allergic Cephazolin 2g IV, 8-hourly, or</div><div class=\"answer-line\">Vancomycin 1.5g IV, 12-hourly if immediate hypersensitivity</div><div class=\"answer-line\">Gonococcal arthritis is considered in sexually active males, but in the absence of rash or urinary</div><div class=\"answer-line\">symptoms this is less likely, and he is more likely to have a standard gram-positive infection ie Staph</div><div class=\"answer-line\">Aureus or Strep. If cultures or Gram stain suggest gonococcus then should be treated for disseminated</div><div class=\"answer-line\">gonococcus with iv ceftriaxone. eTG recommends empiric therapy only with flucloxacillin until cultures</div><div class=\"answer-line\">come back to direct therapy.</div><div class=\"answer-line\">Ref: eTG antibiotic and rheumatology sections</div><div class=\"answer-line\"><strong>Pass mark: 8/12 </strong></div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"(Total 18 marks) A 35-year-old man has been intubated in your department overnight after ingestion of an unknown quantity of alcohol and methadone. The indication for intubation was airway protection secondary to a low GCS. He has a normal BSL, and a CT brain performed shortly after intubation has also been reported as normal. He has spent the night in the ED as no ICU beds were available. You are considering extubation of the patient in your department.","parts":[{"id":"a","label":"Part A","prompt":"List 6 clinical criteria that must be met to ensure this patient is suitable for extubation in the ED? (6 marks)"},{"id":"b","label":"Part B","prompt":"List five non-clinical criteria must be met to ensure safe extubation of this patient in your department. (5 marks)"},{"id":"c","label":"Part C","prompt":"List three pieces of equipment you would have immediately available prior to extubation\n• f this patient in the ED.\n(3 marks) The patient is successfully extubated. He currently has adequate respiratory function and is GCS 15."},{"id":"d","label":"Part D","prompt":"State your 4 subsequent steps in the management of this patient.\n(4 marks) ‘"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>12/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(Any of following options for 1 mark each)</div><div class=\"answer-line\">Resolution of underlying issue that caused need for intubation</div><div class=\"answer-line\">Spontaneously breathing</div><div class=\"answer-line\">Resp parameters: O2 sats &gt; 95% on FiO2 &lt; 40%, PEEP &lt; 5, RR &lt; 30, TV &gt; 6mL/kg</div><div class=\"answer-line\">Haemodynamic stability without need for inotropic support</div><div class=\"answer-line\">Sedation &amp; paralysis worn off</div><div class=\"answer-line\">Not a difficult intubation</div><div class=\"answer-line\">Obey commands</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Staff skilled in managing extubation (Nursing &amp; Medical)</div><div class=\"answer-line\">Staff available who can reintubate if required</div><div class=\"answer-line\">Equipment available for reintubation</div><div class=\"answer-line\">Rest of department workload suitable</div><div class=\"answer-line\">No more suitable place for this to occur (eg no ICU beds)</div><div class=\"answer-line\">3-</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Suction</div><div class=\"answer-line\">O2 mask &amp; supply</div><div class=\"answer-line\">NIV set-up</div><div class=\"answer-line\">Intubation drugs &amp; paralysis agents (Suxamethonium 1.5mg/kg drawn up)</div><div class=\"answer-line\">Equipment for urgent reintubation</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospital      The Royal Brisbane &amp;Women Hospital           Redcliffe  and Caboolture                  Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong>                Emergency Department                            Emergency Departments                  Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div><div class=\"answer-line\">On-going observation and monitoring of respiratory function</div><div class=\"answer-line\">May require admission under appropriate team if any clinical concerns</div><div class=\"answer-line\">Complete history and examination of pt to look for other medical conditions and determine if any</div><div class=\"answer-line\">suicidality to presenting complaint</div><div class=\"answer-line\">Arrange review by alcohol and drugs services +/- social worker +/- psych services</div><div class=\"answer-line\">Pass mark (12/16)</div><div class=\"answer-line\">permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"(Total 18 marks) You are working in the retrieval service when you receive a call for advice from a junior medical officer who is working in a small rural hospital 300km from the tertiary centre. They have a 34-year-old male patient who has sustained burns to his chest and arms whilst lighting a fire on his farm.","parts":[{"id":"a","label":"Part A","prompt":"List 2 different methods that could be used to estimate the TBSA% of this patient’s burns. (2 Marks)"},{"id":"b","label":"Part B","prompt":"What key features of this patient’s assessment would suggest the presence of airway burns. (4 Marks)"},{"id":"c","label":"Part C","prompt":"What features in patient presentation and assessment would indicate IV Fluids should be given? (3 Marks)"},{"id":"d","label":"Part D","prompt":"If fluids are required, outline your advice about how to calculate the initial fluid requirements for this patient."},{"id":"e","label":"Part E","prompt":"List 6 criteria that would indicate that this patient requires referral to a burns centre for\n• ngoing management.\n(3 Marks)"},{"id":"f","label":"Part F","prompt":"Complete the table by listing 4 early (<72hrs) and 4 long term (>72hrs) complications that may occur from this patient’s burns. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>12/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Lund and Browder chart</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Rule of nines</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Palmar surface</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>•</td><td>Stridor</td></tr><tr><td>•</td><td>Hoarse voice</td></tr><tr><td>•</td><td>Carbonaceous sputum</td></tr><tr><td>•</td><td>Singed facial hair</td></tr><tr><td>•</td><td>Nasal/oral burns</td></tr><tr><td colspan=\"2\">History of fire in a confined space</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>•</td><td>If  &gt;15-20% TBSA for adult patient</td></tr><tr><td>•</td><td>If coexistent traumatic injuries</td></tr><tr><td>•</td><td>If delayed presentation</td></tr><tr><td colspan=\"2\">If inhalation injury/airway burns</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Modified Parkland Formula</td></tr><tr><td>•</td><td>3-4mLs x TBSA% Burn X Weight (kg) = total in first 24hrs</td></tr><tr><td>•</td><td><strong>1/2</strong> Total Fluid Volume to be given in <strong>first 8 hours post burn</strong></td></tr><tr><td>•</td><td><strong>1/2</strong> Total Fluid Volume to be given over <strong>next 16 hours</strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</td></tr><tr><td colspan=\"2\">Brisbane &amp; Women Hospital Emergency</td></tr><tr><td colspan=\"2\"><strong>The Prince Charles Hospital     The Royal Brisbane &amp;Women Hospital     Redcliffe  and Caboolture      Sunshine Coast U Hospital </strong></td></tr><tr><td colspan=\"2\"><strong> Emergency Department                 Emergency Departments       Emergency Departments</strong><strong> </strong></td></tr><tr><td colspan=\"2\"><strong>     Emergency Department </strong></td></tr><tr><td>•</td><td>Burns &gt; 10 % TBSA in an Adult (partial and full thickness)</td></tr><tr><td>•</td><td>Full thickness burns &gt; 5% TBSA</td></tr><tr><td>•</td><td>Burns to special areas (eg face, hands, feet, perineum, genitalia, and major joints)</td></tr><tr><td>•</td><td>Circumferential burns</td></tr><tr><td>•</td><td>Burns in the presence of major trauma</td></tr><tr><td>•</td><td>Burns with significant co-morbidity (Type 1 Diabetes, CCF)</td></tr><tr><td>•</td><td>Unable to managed in the current level of hospital</td></tr><tr><td colspan=\"2\">Burns with inhalation injury</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Immediate</div><div class=\"answer-line\">Infection/Sepsis</div><div class=\"answer-line\">Hypovolaemia from fluid loss</div><div class=\"answer-line\">Electrolyte disturbances – Hypokalaemia, Hyperkalaemia</div><div class=\"answer-line\">Acute Respiratory Distress Syndrome</div><div class=\"answer-line\">Acute Kidney Injury</div><div class=\"answer-line\">Carbon Monoxide Poisoning</div><div class=\"answer-line\">Hypothermia</div><div class=\"answer-line\">Rhabdomyolysis</div><div class=\"answer-line\">Chest rigidity &amp; hypoventilation from eschar</div><div class=\"answer-line\">Long term</div><div class=\"answer-line\">GI Ulcer</div><div class=\"answer-line\">Disfigurement -Cosmetic/Scarring</div><div class=\"answer-line\">Loss of function</div><div class=\"answer-line\">Loss of income/employment</div><div class=\"answer-line\">Contractures</div><div class=\"answer-line\">Psychological</div><div class=\"answer-line\">Restrictive chest wall/lung disease</div><div class=\"answer-line\"><strong>Pass mark: 12/18 </strong></div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"(Total 12 Marks) A 45 year old man known to be HIV positive presents to your department with fever, non-productive cough,\n\nweight loss and mild confusion.\nHis vital signs are:\n\nPR\n105/min\n\nBP\n110/70\n\nSats\n94% on room air\n\nTemp 38.6 degrees\n\nBSL\n5.4","parts":[{"id":"a","label":"Part A","prompt":"List 4 important differential diagnoses to be considered in this patient.\n(2 marks)"},{"id":"b","label":"Part B","prompt":"List and justify 4 specific investigations that will help in differentiating the cause of this patient’s illness (4 marks) Investigation Reason"},{"id":"c","label":"Part C","prompt":"The patient’s new girlfriend is in attendance. She is concerned regarding her risk of\ncontracting HIV. List 4 factors that influence your decision to commence Post Exposure\nProphylaxis (PEP) in this patient."},{"id":"d","label":"Part D","prompt":"List 4 things that a clinician must discuss with patients to whom they are prescribing PEP. (4 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Pneumonia – streptococcal and atypicals such as PJP</td></tr><tr><td>•</td><td>Tuberculosis</td></tr><tr><td>•</td><td>Meningitis</td></tr><tr><td>•</td><td>Toxoplasmosis</td></tr><tr><td>•</td><td>Cerebral lymphoma</td></tr><tr><td>•</td><td>Cryptococcosis</td></tr><tr><td>•</td><td>HIV encephalopathy</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Investigation</td><td>Reason</td></tr><tr><td>Bloods – viral load/CD4 count</td><td>Identifying AIDs defining conditions</td></tr><tr><td>CXR</td><td>Pneumonia/TB</td></tr><tr><td>LP</td><td>Meningitis/Cryptococcosis</td></tr><tr><td>CT head</td><td>Cerebral lymphoma/toxoplasmosis</td></tr><tr><td colspan=\"2\">0.5 mark only if investigation not adequately justified.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Type of intercourse (nil indication for oral intercourse)</td></tr><tr><td>•</td><td>Time of exposure (if &gt; 72 hours minimal evidence for commencement of PEP)</td></tr><tr><td>•</td><td>Viral load (if source patient has undetectable viral load no PEP needed)</td></tr><tr><td colspan=\"2\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</td></tr><tr><td colspan=\"2\">Brisbane &amp; Women Hospital Emergency</td></tr><tr><td colspan=\"2\"><strong>The Prince Charles Hospital     The Royal Brisbane &amp;Women Hospital     Redcliffe  and Caboolture      Sunshine Coast U Hospital </strong></td></tr><tr><td colspan=\"2\"><strong> Emergency Department                 Emergency Departments       Emergency Departments</strong><strong> </strong></td></tr><tr><td colspan=\"2\"><strong>     Emergency Department </strong></td></tr><tr><td>•</td><td>If she is pregnant (commencement of PEP in pregnancy needs discussion with ID</td></tr><tr><td colspan=\"2\">specialist)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• PEP provides high levels of protection but does not prevent 100% of infections</div><div class=\"answer-line\">• the importance of adherence</div><div class=\"answer-line\">• the potential adverse effects of treatment and possible drug interactions</div><div class=\"answer-line\">• measures for preventing re-exposure to HIV / safe sex</div><div class=\"answer-line\">• follow-up HIV testing</div><div class=\"answer-line\">• HIV seroconversion signs and symptoms</div><div class=\"answer-line\">Pass mark      8/12</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"(Total 12 Marks) A 39 year old woman presents to your emergency department complaining of a headache. She is G1 P0 at 36 weeks gestation.\nHer vital signs are:\n\nTemp\n36.7\n\nHR\n\nBP\n150/90\n\nSaO2\n99% RA Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 5 differential diagnoses for this patient?\n(5 marks)"},{"id":"b","label":"Part B","prompt":"For the table below, list examination or investigation features that help you to differentiate between these possible diagnoses? Include a"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Pre-eclampsia </strong></td></tr><tr><td>•</td><td>Hypertension in pregnancy</td></tr><tr><td>•</td><td><span class=\"answer-source-red\">Cerebral venous thrombosis</span></td></tr><tr><td>•</td><td>Migraine</td></tr><tr><td>•</td><td>SAH</td></tr><tr><td>•</td><td>CVA</td></tr><tr><td>•</td><td>Meningo-encephalitis</td></tr><tr><td>•</td><td>Tension headache</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>differentiate between these possible diagnoses?</td><td></td></tr><tr><td><strong>Include a justification</strong>.</td><td>(7 marks, 0.5 for each space) 5/7</td></tr><tr><td>Reflexes</td><td>Presence of clonus <span class=\"answer-source-red\">and hyper-reflexia- pre </span></td></tr><tr><td><span class=\"answer-source-red\">eclampsia </span></td><td></td></tr><tr><td>Neurological exam</td><td>Focal deficit<span class=\"answer-source-red\">- ICH/SAH/cerebral venous </span></td></tr><tr><td><span class=\"answer-source-red\">thrombosis </span></td><td></td></tr><tr><td>FBC</td><td>Low platelets (HELLP), haemolysis</td></tr><tr><td>ELFTs</td><td>HELLP, elevated creatinine</td></tr><tr><td>WTU</td><td>Proteinuria</td></tr><tr><td>Uric acid</td><td>Elevated in pre-eclampsia</td></tr><tr><td>CT brain</td><td>If features of SAH or focal deficit</td></tr><tr><td>CTG monitoring<span class=\"answer-source-red\">/ bedside USS </span></td><td>Fetal well-being</td></tr><tr><td>without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</td><td></td></tr><tr><td>Brisbane &amp; Women Hospital Emergency</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"(Total 12 marks) You are the ED consultant on the evening shift in a busy tertiary hospital. The following patient is brought in by ambulance after an altercation with a workmate.\nHis vital signs are as follows:\n\nHR\n90/min\n\nBP\n110 /75 mmHg\n\nSpO2\n96% on room air\n\nGCS\n15/15","parts":[{"id":"a","label":"Part A","prompt":"Describe the key feature of this injury. (1 Marks)"},{"id":"b","label":"Part B","prompt":"List 5 signs that would raise concern that this patient’s airway is at risk from this injury. (5 marks)"},{"id":"c","label":"Part C","prompt":"The patient develops worsening hypoxia and respiratory distress. List 6 immediate actions you would take to manage this situation? (6 Marks)"}],"propPages":["asset:img5dcc7ff883a909e6f3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Penetrating neck injury with weapon device left in-situ</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Involvement of left anterior triangle in zone 2 of neck</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Hard signs</td></tr><tr><td>-</td><td>Expanding haematoma</td></tr><tr><td>-</td><td>Thrill/bruit</td></tr><tr><td>-</td><td>Air or bubbling in wound</td></tr><tr><td>-</td><td>Haemoptysis</td></tr><tr><td>-</td><td>Tracheal deviation</td></tr><tr><td>-</td><td>Stridor</td></tr><tr><td>-</td><td>Hoarse voice</td></tr><tr><td>-</td><td>Significant or rapidly expanding subcutaneous emphysema</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Maintain airway patency through upright positioning in position of comfort.</div><div class=\"answer-line\">Optimise oxygenation 15L O2 via NRBM (NOT suitable for NIV or HF nasal O2)</div><div class=\"answer-line\">Seek and treat tension pneumothorax or haemothorax</div><div class=\"answer-line\">Notification of anaesthetics/surgical team for attendance and assistance re: possible surgical</div><div class=\"answer-line\">airway/tracheostomy</div><div class=\"answer-line\">Prepare for emergent direct/video assisted laryngoscopy for RSI with Ketamine 2mg/kg and</div><div class=\"answer-line\">Rocuronium 1.2mg/kg</div><div class=\"answer-line\">Prepare for difficult airway. Surgical airway kit open, neck prepped and senior clinician scrubbed</div><div class=\"answer-line\">for surgical airway.</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"(Total marks 12) A 7 year old boy presents to your ED with Right sided testicular pain. You work in a hospital that does not\n• perate on children <10yrs of age.","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses other than testicular torsion? For each diagnosis, state a specific examination finding related to that condition. (8 Marks) Diagnosis Exam finding The registrar looking after the patient reports back to you that the surgical registrar at the local receiving hospital is refusing to accept the patient until an ultrasound has been performed."},{"id":"b","label":"Part B","prompt":"State your actions in response to this. (4 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Epididymo-orchitis</td><td>Tender hot hemiscrotum</td></tr><tr><td>Haematoma</td><td>Brusisng to scrotum/groin</td></tr><tr><td>Inguinal hernia</td><td>Bowel sounds present/reducible</td></tr><tr><td>Torsion appendix testes</td><td></td></tr><tr><td>Orchitis/Epididymoorchitis</td><td></td></tr><tr><td>Trauma (Haematoma, Testicular rupture)</td><td></td></tr><tr><td>Renal colic</td><td></td></tr><tr><td>Inguinal hernia</td><td></td></tr><tr><td>Others acceptable...</td><td></td></tr><tr><td>2. <strong>The registrar looking after the patient reports back to you that the surgical </strong></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Phone Surg reg directly to explain clinical concern and that USS is inappropriate</div><div class=\"answer-line\">Escalate to Surg consultant if any further resistance</div><div class=\"answer-line\">Arrange for immediate transfer of patient, once appropriate ED care instituted</div><div class=\"answer-line\">Consider need for involvement in quality process (will accept a wide range of options</div><div class=\"answer-line\">here)</div><div class=\"answer-line\">Arrange transport to local receiving hospital – private vehicle or ambulance – no delay</div><div class=\"answer-line\">Speak to ED consultant at receiving hospital to advise of time critical emergency &amp; need for</div><div class=\"answer-line\">immediate transfer</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospital     The Royal Brisbane &amp;Women Hospital     Redcliffe  and Caboolture      Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong> Emergency Department                 Emergency Departments       Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div><div class=\"answer-line\">Speak to Surgical Consultant at receiving hospital and escalate to medical superintendant of both</div><div class=\"answer-line\">hospitals if necessary</div><div class=\"answer-line\">Documentation of refusal &amp; your escalation of management</div><div class=\"answer-line\">Medical Superintendant informed</div><div class=\"answer-line\">Make appropriate report –PRIME</div><div class=\"answer-line\">Consider using as M&amp;M case</div><div class=\"answer-line\">For review post event to ensure appropriate WUG to avoid unnecessary delays in time critical</div><div class=\"answer-line\">emergency</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"(Total 12 Marks)\nA 55 year old male patient presents with a painful, swollen foot for the past week.\nHis vital signs are:\n\nTemp\n38.1\n\nHR\n\nBP\n95/50\n\nRR\nO2 Sats 96% RA Questions:","parts":[{"id":"a","label":"Part A","prompt":"Describe the pertinent findings on this X-ray & state the most likely diagnosis. (2 marks) Finding: Diagnosis:"},{"id":"b","label":"Part B","prompt":"What are the likely organisms causing this condition?"},{"id":"c","label":"Part C","prompt":"List 5 groups of patients that may be predisposed to developing this condition.\n(5 marks)"},{"id":"d","label":"Part D","prompt":"List 2 factors that would give the patient with this condition a poorer prognosis\n(2 marks)"}],"propPages":["asset:img01304cb3ba2571a863"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Extensive gas in soft tissues of dorsum &amp; plantar aspects of foot</div><div class=\"answer-line\">No obvious fractures (NOT a compound fracture)</div><div class=\"answer-line\">= Necrotising fasciitis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Group A Strep</div><div class=\"answer-line\">Clostridium perfringens</div><div class=\"answer-line\">Staph aureus</div><div class=\"answer-line\">Vibrio (Salt-water)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Diabetics</div><div class=\"answer-line\">Alcoholics</div><div class=\"answer-line\">Immunocompromised</div><div class=\"answer-line\">Malignancy</div><div class=\"answer-line\">HIV infected patients</div><div class=\"answer-line\">Transplant patients</div><div class=\"answer-line\">Post-op patients</div><div class=\"answer-line\">Chronic liver disease</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Advanced age</div><div class=\"answer-line\">Significant comorbidities</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospital     The Royal Brisbane &amp;Women Hospital     Redcliffe  and Caboolture      Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong> Emergency Department                 Emergency Departments       Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div><div class=\"answer-line\">Underlying circulatory compromise of limb</div><div class=\"answer-line\">Late presentation</div><div class=\"answer-line\">Delay to surgical debridement</div><div class=\"answer-line\">Passmark: 8/12</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"(Total marks 12)\nA 56-year old patient presents to your emergency department on a Saturday evening.\nHe is known to have end-stage renal failure and is on continuous ambulatory peritoneal dialysis. He is complaining\n• f fever and diffuse abdominal pain.","parts":[{"id":"a","label":"Part A","prompt":"State the criteria required for the diagnosis of peritoneal dialysis associated peritonitis. (3 marks)"},{"id":"b","label":"Part B","prompt":"Name three organisms commonly causing peritoneal dialysis associated peritonitis (3 marks)"},{"id":"c","label":"Part C","prompt":"Complete the following table for the empiric treatment of suspected peritoneal dialysis peritonitis. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Cloudy dialysate and ≥2 of fever, abdo pain, nausea, vomiting, diarrhoea</div><div class=\"answer-line\">PD fluid shows WCC&gt; 100 /mm3 of which ≥50% are PMN</div><div class=\"answer-line\">Positive Gram stain or culture</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Staph epidermis/ coagulase-negative staph (25-40%)</div><div class=\"answer-line\">Staph aureus (10-15%)</div><div class=\"answer-line\">Strep species</div><div class=\"answer-line\">Gram-negatives</div><div class=\"answer-line\">Anaerobic bacteria</div><div class=\"answer-line\">Fungi</div><div class=\"answer-line\">Must have bold</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">Staph epidermis/ coagulase-negative staph (25-40%)</td></tr><tr><td colspan=\"3\">Staph aureus (10-15%)</td></tr><tr><td colspan=\"3\">Strep species</td></tr><tr><td colspan=\"3\">Gram-negatives</td></tr><tr><td colspan=\"3\">Anaerobic bacteria</td></tr><tr><td colspan=\"3\">Fungi</td></tr><tr><td colspan=\"3\">Must have bold</td></tr><tr><td colspan=\"3\">(6 marks). – 3 lines only in table for 6 marks</td></tr><tr><td>Drug (1mark)</td><td>Dose (0.5 mark)</td><td>Frequency and route</td></tr><tr><td colspan=\"3\">(0.5 mark)</td></tr><tr><td>Cefazolin</td><td>15mg/kg</td><td>Intra-peritoneal, daily</td></tr><tr><td>Gentamicin</td><td>0.6mg/kg up to 50mg</td><td>Intra-peritoneal, daily</td></tr><tr><td>Heparin</td><td>500 U/L</td><td>Intra-peritoneal, each</td></tr><tr><td colspan=\"3\">exchange</td></tr><tr><td>Nystatin</td><td>500,000 IU</td><td>Oral qid</td></tr><tr><td colspan=\"3\">Must have bold</td></tr><tr><td colspan=\"3\">Source Queensland Health peritoneal dialysis peritonitis clinical pathway; Tintinalli</td></tr><tr><td colspan=\"3\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</td></tr><tr><td colspan=\"3\">Brisbane &amp; Women Hospital Emergency</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"(Total Marks 12) A 4-month-old male infant is brought to the ED with 2 days history of progressive irritability and fever.\nHis vital signs are:\n\nHR 180\n\nRR 38\n\nSat 96%\n\nTemp 38.7\nHis photograph is included in the props booklet: Questions:","parts":[{"id":"a","label":"Part A","prompt":"List the key features of the above photograph. (3 marks)"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"List 3 other possible causes for the above presentation.\n(3 marks)"},{"id":"d","label":"Part D","prompt":"List your immediate management steps, including any drugs, doses and end points. (5 marks)"}],"propPages":["asset:img8f6f68c85c4690af49"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Distressed infant</div><div class=\"answer-line\">Erythema to face, chest, abdomen, perineum and front of both legs</div><div class=\"answer-line\">Evidence of extensive DESQUAMATION to upper chest, right arm, abdomen, perineum and</div><div class=\"answer-line\">right leg</div><div class=\"answer-line\">No involvement of mucous membranes</div><div class=\"answer-line\">Difficult to give a % as can’t see back, extensive desquamation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Most likely Staphylococcal Scalded Skin Syndrome – exotoxin from Staph Aureus infection</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Stevens Johnson syndrome- TENS (has mucosal involvement)</div><div class=\"answer-line\">Burns- chemical, thermal</div><div class=\"answer-line\">Non-accidental injury</div><div class=\"answer-line\">Dermatitis- contact/exfoliative</div><div class=\"answer-line\">Necrotising fasciitis</div><div class=\"answer-line\">Omphalitis</div><div class=\"answer-line\">Staph or strep infection spreading (without exotoxin)</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospital     The Royal Brisbane &amp;Women Hospital     Redcliffe  and Caboolture      Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong> Emergency Department                 Emergency Departments       Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Fluid resuscitation- normal saline if markers of shock – 20mls/kg normal saline</div><div class=\"answer-line\">Check BSL- ensure normoglycemia</div><div class=\"answer-line\">Temperature control- potential for hypothermia- cover and keep warm; monitor core</div><div class=\"answer-line\">temperature</div><div class=\"answer-line\">IV antibiotics- Flucloxacillin 50mg/kg</div><div class=\"answer-line\">Send swab for M/C/S to guide further Abs</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Analgesia- will need IV opiates morphine 0.1mg/kg doses, anticipate need for infusion</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"(Total 18 Marks) A 38 year old female presents to your ED with a referral letter from her GP requesting a blood transfusion for anaemia. She does not have any obvious source of bleeding other than a history of menorrhagia. Her FBC is shown below.\n\nHb 74 g/L\nMCV 75\n\nWCC 7.4\nPlt 380 Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 5 possible causes for her anaemia.\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List three indications for a blood transfusion in this patient? The patient is deemed to require a blood transfusion and you have a discussion with her regarding consent for this. However, she refuses the transfusion due to concerns about the risks."},{"id":"c","label":"Part C","prompt":"List 4 early and 4 late complications of blood transfusion.\n(8 marks) Early Complications Late Complications"},{"id":"d","label":"Part D","prompt":"List 2 alternative treatment options you could consider in this patient.\n(2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>12/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Iron deficiency anaemia from blood loss (likely menstrual or GIT)</div><div class=\"answer-line\">Iron deficiency anaemia from poor dietary intake</div><div class=\"answer-line\">Megaloblastic anaemia from folate/B12 deficiency</div><div class=\"answer-line\">Haemolysis</div><div class=\"answer-line\">Anaemia of chronic disease</div><div class=\"answer-line\">Bone marrow malignancy or infiltration</div><div class=\"answer-line\">Haemoglobinopathy</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hb &lt; 70 g/L</div><div class=\"answer-line\">Symptomatic anaemia (eg SOB, Syncope, Heart failure)</div><div class=\"answer-line\">Significant comorbidity (eg cardiac disease, malignancy)</div><div class=\"answer-line\">The patient is deemed to require a blood transfusion and you have a discussion with her</div><div class=\"answer-line\">regarding consent for this.  However, she refuses the transfusion due to concerns about the risks.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Any of the following for up to 4 marks:</div><div class=\"answer-line\">Any of the following for up to 4 marks:</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Iron oral supplements</div><div class=\"answer-line\">Iron infusion</div><div class=\"answer-line\">Conservative Mx with consideration of EPO if no improvement in the next few weeks.</div><div class=\"answer-line\">Passmark: 12/18</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal</div><div class=\"answer-line\">Brisbane &amp; Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"(Total 18 Marks) You are working as the doctor on a helicopter retrieval service that is dispatched to retrieve a patient that has collapsed on a dive boat on a nearby reef. Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 6 diving related and 6 non-diving related differential diagnoses for this collapse.\n(6 marks) Diving related (0.5 Marks each) Non-diving related (0.5 Marks each) 2. Indicate 6 aspects of the history that might help differentiate the cause of the collapse. (6 marks)"},{"id":"b","label":"Part B","prompt":"List 4 body systems that may be affected by decompression illness and give one\nclinical feature for each. (4 marks) Body system Example"},{"id":"c","label":"Part C","prompt":"Outline 2 key considerations whilst retrieving this patient by helicopter.\n(2 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>12/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Diving related:</div><div class=\"answer-line\">CAGE/DCI</div><div class=\"answer-line\">Toxic gas CO2, CO, hydrocarbon</div><div class=\"answer-line\">Immersion pulmonary oedema</div><div class=\"answer-line\">Near drowning</div><div class=\"answer-line\">Hypothermia</div><div class=\"answer-line\">Marine envenomation (coneshell, box jelly/irukanji, blue-ringed octopus etc)</div><div class=\"answer-line\">Non-diving related:</div><div class=\"answer-line\">Hypoglycaemia</div><div class=\"answer-line\">Seizure</div><div class=\"answer-line\">ICH/CVA</div><div class=\"answer-line\">CVS collapse (ACS, arrhythmia, PE)</div><div class=\"answer-line\">Trauma</div><div class=\"answer-line\">Drug/medication intoxication</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Diving history:</td><td>Symptoms preceding diving?</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">each.</div><div class=\"answer-line\">(4 marks) 2/4</div><div class=\"answer-line\">CNS (confusion, headache, unsteadiness, ALOC)</div><div class=\"answer-line\">Spinal (sensory/motor deficits: esp paraparesis, urine retention, loss of anal tone)</div><div class=\"answer-line\">Pulmonary (chest pain, dyspnoea, hypoxia)</div><div class=\"answer-line\">Musculoskeletal (myalgia, arthralgias)</div><div class=\"answer-line\">Vestibular (vertigo, tinnitus, hearing loss, ataxia)</div><div class=\"answer-line\">Skin (rash)</div><div class=\"answer-line\">Lymphatic (swelling)</div><div class=\"answer-line\">4. Outline 2 key considerations whilst retrieving this patient by helicopter.</div><div class=\"answer-line\">(2 Marks) 1/2</div><div class=\"answer-line\">Retrieval: winch from dive deck vs meet boat onshore</div><div class=\"answer-line\">Bubble injury considerations: Maintain horizontal position if concern re CAGE. Patient needs to be flown as</div><div class=\"answer-line\">close to sea level altitude as safely possible.</div><div class=\"answer-line\">ABCDE/supportive care: Needs highest flow O2 available, restore volume with prompt IV fluids, warming</div><div class=\"answer-line\">and drying</div><div class=\"answer-line\">Addressing differential causes of collapse as indicated</div><div class=\"answer-line\">Urgent transport to nearest centre with recompression chamber. (Delay &gt;hrs to recompression in CAGE=</div><div class=\"answer-line\">poorer outcomes)</div><div class=\"answer-line\">Passmark: 12/18</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"(Total 12 Marks) A 59 year old male presents to your ED with syncope. His ECG shows a broad complex tachycardia. Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 4 different causes of a broad complex tachycardia\n(2 Marks)"},{"id":"b","label":"Part B","prompt":"List 4 clinical features that increase the likelihood of Ventricular Tachycardia (VT)\n(4 Marks)"},{"id":"c","label":"Part C","prompt":"List 4 ECG features that increase the likelihood of VT\n(4 marks)"},{"id":"d","label":"Part D","prompt":"List 2 medications used to treat stable VT\n(2 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>•</td><td>SVT with aberrant conduction due to bundle branch block</td></tr><tr><td>•</td><td>SVT with aberrant conduction due to the Wolff-Parkinson-White syndrome</td></tr><tr><td>•</td><td>Pace-maker mediated tachycardia</td></tr><tr><td>•</td><td>Metabolic derangements e.g. hyperkalaemia</td></tr><tr><td>•</td><td>Poisoning with sodium-channel blocking agents (e.g. tricyclic antidepressants)</td></tr><tr><td colspan=\"2\"><strong>2.</strong><strong> </strong><strong>List 4 clinical features that increase the likelihood of VT    </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>•</td><td>Age &gt; 35</td></tr><tr><td>•</td><td>Structural heart disease</td></tr><tr><td>•</td><td>Ischaemic heart disease</td></tr><tr><td>•</td><td>Previous MI</td></tr><tr><td>•</td><td>Congestive heart failure</td></tr><tr><td>•</td><td>Cardiomyopathy</td></tr><tr><td>•</td><td>Family history of sudden cardiac death (suggesting conditions such as HOCM, congenital long QT</td></tr><tr><td colspan=\"2\">syndrome, Brugada syndrome or arrhythmogenic right ventricular dysplasia that are associated with</td></tr><tr><td colspan=\"2\">episodes of VT)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>•</td><td>Absence of typical RBBB or LBBB morphology</td></tr><tr><td>•</td><td>Extreme axis deviation (“northwest axis”)</td></tr><tr><td>•</td><td>Very broad complexes (&gt;160ms)</td></tr><tr><td>•</td><td>AV dissociation</td></tr><tr><td>•</td><td>Capture beats</td></tr><tr><td>•</td><td>Fusion</td></tr><tr><td>•</td><td>Positive or negative concordance throughout the chest leads</td></tr><tr><td>•</td><td>Brugada’s sign</td></tr><tr><td>•</td><td>Josephson’s sign</td></tr><tr><td colspan=\"2\">RSR’ complexes with a taller left rabbit ear</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Amiodarone 5mg/kg</td></tr><tr><td>•</td><td>Procainamide 50mg/min</td></tr><tr><td>•</td><td>Lignocaine 1mg/kg</td></tr><tr><td>•</td><td>Sotalol 1mg/kg</td></tr><tr><td>•</td><td>Magnesium 10mmol                                  Pass mark: 8/12</td></tr><tr><td colspan=\"2\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</td></tr><tr><td colspan=\"2\">Women Hospital Emergency</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"(Total 12 Marks) Your Registrar has asked you to review a 28-year-old man who is having a reduction of his fractured left radius performed under Bier’s block using IV Prilocaine. Fifteen minutes into the procedure he is complaining of shortness of breath and light-headedness. On examination, he appears cyanotic with oxygen saturation of 85% on pulse oximetry.","parts":[{"id":"a","label":"Part A","prompt":"List 3 differential diagnoses for his deterioration?\n(3 marks)"},{"id":"b","label":"Part B","prompt":"List 2 investigations you would do in this patient with justification of how it will aid in your diagnosis? (2 marks)"},{"id":"c","label":"Part C","prompt":"List 3 treatment options for the most likely diagnosis?\n(3 marks)"},{"id":"d","label":"Part D","prompt":"List 4 contraindications, in any patient, to performing a Bier’s Block .\n(4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Your Registrar has asked you to review a 28 year old man who is having a reduction of his fractured left</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">radius performed under Bier’s block using Prilocaine. 15 minutes into the procedure he is complaining of</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">shortness of breath and light-headedness.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">On examination, he appears cyanotic with oxygen saturation of 85% on pulse oximetry.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"(Total Marks 12) You join an outer urban Emergency Department as a new consultant. The department occasionally provides road retrieval and inter-hospital transfer services in support of the ambulance service, using a nurse and doctor from the department. The Department Director asks you to formalise the arrangements and make recommendations for the safe provision of these retrievals. Questions:","parts":[{"id":"a","label":"Part A","prompt":"List two categories of Personal Protective Equipment (PPE) that should be provided to staff and give an example of each. (2 Marks) Categories Example"},{"id":"b","label":"Part B","prompt":"List four patient monitoring modalities required for the safe transportation of patients. (4 Marks)"},{"id":"c","label":"Part C","prompt":"List three important items of non-clinical equipment that might be needed. (3 marks)"},{"id":"d","label":"Part D","prompt":"What clinical governance review processes are required? (3 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(needs these two broad categories, with examples)</div><div class=\"answer-line\">a. Against body fluid exposure – eg glasses, gloves, aprons/gowns</div><div class=\"answer-line\">b. Against extreme environments – eg boots, dedicated long sleeve clothing, hats/helmets, sun</div><div class=\"answer-line\">and cold protection</div><div class=\"answer-line\"><strong>2.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">(4 out of these 5 needed. This taken specifically from ACEM guidelines)</div><div class=\"answer-line\">Continuous ECG</div><div class=\"answer-line\">Pressure monitoring – invasive and non-invasive</div><div class=\"answer-line\">Patient Oxygenation with continuous pulse oximetry</div><div class=\"answer-line\">Patient Ventilation with wave form capnography</div><div class=\"answer-line\">Ventilator alarms including high pressure and disconnection</div><div class=\"answer-line\"><strong>3.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">(4 of these, or other sensible suggestions)</div><div class=\"answer-line\">Communication – phones</div><div class=\"answer-line\">Documentation and pens</div><div class=\"answer-line\">Taxi vouchers</div><div class=\"answer-line\">Spare batteries for equipment</div><div class=\"answer-line\">Torches and/or head torches</div><div class=\"answer-line\"><strong>4.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">(Can be formatted any way, but needs to include an audit of events and using this to feedback</div><div class=\"answer-line\">into future practice)</div><div class=\"answer-line\">Audit of cases</div><div class=\"answer-line\">i. Tasking</div><div class=\"answer-line\">ii. Staffing mix and seniority</div><div class=\"answer-line\">iii. Equipment performance</div><div class=\"answer-line\">iv. Clinical decisions and patient outcomes</div><div class=\"answer-line\">v. Closed loop of feedback to staff and to inform future practice</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"(Total Marks 12) A 24-year-old male is brought to your Emergency Department by his friends after an altercation. He is moribund, with no palpable radial pulses and a thready carotid pulse, with a HR of 155 bpm. His photograph is shown below:","parts":[{"id":"a","label":"Part A","prompt":"State three (3) important features in this clinical photograph and their significance. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 2 ultrasonographic signs that would be consistent with pericardial\ntamponade on ultrasound?"},{"id":"c","label":"Part C","prompt":"List 2 indications for emergency department thoracotomy for penetrating\ntrauma. (2 marks)"},{"id":"d","label":"Part D","prompt":"List five potential complications from resuscitative thoracotomy? (5 marks)"}],"propPages":["asset:img72df60bcf3bfbcc554"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">3 stab wounds to back/thorax</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Active bleeding</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Proximate to heart – high risk of cardiac injury, likely Pneumo or HaemoTx</div><div class=\"answer-line\">2.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pericardial effusion</div><div class=\"answer-line\">•</div><div class=\"answer-line\">R sided heart collapse during diastole</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Cardiac arrest &lt;15 minutes with initial signs of life <em><strong> </strong></em></div><div class=\"answer-line\">•</div><div class=\"answer-line\">Systolic blood pressure below 50 mm Hg after fluid resuscitation</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Severe shock with clinical signs of cardiac tamponade</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">a. Coronary artery injury/ligation</div><div class=\"answer-line\">b. Phrenic Nerve laceration</div><div class=\"answer-line\">c. Diaphragmatic injury</div><div class=\"answer-line\">d. Chest wall vascular injury (intercostals, internal mammary)</div><div class=\"answer-line\">e. Infection</div><div class=\"answer-line\">f.</div><div class=\"answer-line\">Health care worker body fluid exposure</div><div class=\"answer-line\">Total marks=12</div><div class=\"answer-line\">Passmark = 8/12</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"(Total Marks 12) A 14 year old girl presents to ED with a rash, as seen in the accompanying clinical photograph. The rash has been present for the last 24 hours. She has been playing rugby league today and has a headache. She has had heavy PV bleeding for the past hour. B-hCG is negative. She appears alert and active.\nHer vital signs are as follows:\n\nGCS\n15/15\n\nHR\n\nRR\n\nSpO2\n100% in room air\n\nTemp\n36.5 C CRT < 2\n\nBP\n119/80 Questions:","parts":[{"id":"a","label":"Part A","prompt":"Describe the main features present. You perform a full blood count."},{"id":"b","label":"Part B","prompt":"List 3 other investigations that you would perform in ED for this patient, with\njustification (6 marks) Investigation Justification 3. The patient’s FBC shows the following:\n\nHb\n112 g/dL (115-165) MCV 72fL (80-100)\n\nWCC\n6 x109 /L (4-11) Neutrophils 47% (40-70%)\nLymphocytes 30%\n(14-45%) Monocytes 6% (4-13%) Eosinophils 1% (0-7%) Basophils 0% (0-3%) Plt 2 x 109 /L (150-400) What is the most likely diagnosis in this patient? (2 marks)"},{"id":"c","label":"Part C","prompt":"Her PV bleeding increases and is difficult to control. Her GCS is now 12. List 2 specific treatments you would give as part of your management to stop her bleeding"}],"propPages":["asset:img1ea1d6c0dde2b71895"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Petechiae &amp; Purpura on both legs</div><div class=\"answer-line\">Bruising to upper thighs</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Investigations:</div><div class=\"answer-line\"><strong>Coagulation profile – investigate possible bleeding disorder and/or DIC </strong></div><div class=\"answer-line\">Urea and creatinine – AKI in MAHA or TTP</div><div class=\"answer-line\">CT head if low platelets in context of trauma</div><div class=\"answer-line\">LFTs re: DIC and haematological malignancy</div><div class=\"answer-line\">X-match/G+H re: possible need for transfusion</div><div class=\"answer-line\">Other reasonable investigations as suggested by candidates (examiner discretion), but would not include:</div><div class=\"answer-line\">Septic screen/blood cultures (stem suggests well, afebrile)</div><div class=\"answer-line\">B-hCG – given in stem</div><div class=\"answer-line\">BSL – generic, non-contributory</div><div class=\"answer-line\">VBG – generic, non-contributory in this setting (not shocked, Hb can wait)</div><div class=\"answer-line\">Candidates must have bold plus 2 others with justification for full marks</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospita       The Royal Brisbane &amp;Women Hospital       Redcliffe  and Caboolture      Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong>  Emergency Department                  Emergency Departments        Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Hb</td><td>112 g/dL</td><td>(115-165)</td></tr><tr><td>MCV</td><td>72fL</td><td>(80-100)</td></tr><tr><td>WCC</td><td>6 x109 /L</td><td>(4-11)</td></tr><tr><td>Neutrophils</td><td>47%</td><td>(40-70%)</td></tr><tr><td>Lymphocytes 30%</td><td>(14-45%)</td><td></td></tr><tr><td>Monocytes</td><td>6%</td><td>(4-13%)</td></tr><tr><td>Eosinophils</td><td>1%</td><td>(0-7%)</td></tr><tr><td>Basophils</td><td>0%</td><td>(0-3%)</td></tr><tr><td>Plt</td><td>2  x 109 /L</td><td>(150-400)</td></tr><tr><td>What is the most likely diagnosis in this patient?</td><td>(2 marks)</td><td></td></tr><tr><td colspan=\"3\">Immune Thrombocytopenic Purpura</td></tr><tr><td colspan=\"3\">4. Her PV bleeding increases and is difficult to control.  Her GCS is now 12. List 2 specific treatments</td></tr><tr><td colspan=\"3\">you would give as part of your management to stop her bleeding</td></tr><tr><td colspan=\"3\">(2 marks)</td></tr><tr><td colspan=\"3\">Intravenous Immunoglobulin</td></tr><tr><td colspan=\"3\">IV Methylprenisolone</td></tr><tr><td colspan=\"3\">IV platelets</td></tr><tr><td colspan=\"3\">Total 12 marks</td></tr><tr><td colspan=\"3\">Expected candidate score for just at standard: 7/12</td></tr><tr><td colspan=\"3\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</td></tr><tr><td colspan=\"3\">Women Hospital Emergency</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"(Total marks 12) You are the consultant on the morning shift and just before handover the night registrar asks you to whether he should complete a death certificate for a 78-year-old man who died in the emergency department overnight. He had advanced dementia and was suspected to have a ruptured abdominal aortic aneurysm which had been previously deemed unsuitable for surgical intervention by the vascular surgeons.","parts":[{"id":"a","label":"Part A","prompt":"List six situations where a death is notifiable to the coroner (6 marks)"},{"id":"b","label":"Part B","prompt":"State one important consideration that is required after notifiable death is reported to the coroner or the police (1 mark)"},{"id":"c","label":"Part C","prompt":"List five actions required by a medical officer in the event of a non-notifiable death in the department (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Identity of the person is unknown</div><div class=\"answer-line\">Violent or unnatural Death</div><div class=\"answer-line\">(accident/suicide/homicide/overdose/snakebite/anaphylaxis/drowning/electrocution/</div><div class=\"answer-line\">work-place)</div><div class=\"answer-line\">Death in suspicious circumstances (homicide suspected)</div><div class=\"answer-line\">Healthcare-related death (healthcare caused/contributed to the death or failure to</div><div class=\"answer-line\">provide care)</div><div class=\"answer-line\">Cause of death certificate has not been issued and is not likely to be issued (not</div><div class=\"answer-line\">able to ascertain cause of death)</div><div class=\"answer-line\">Death in care</div><div class=\"answer-line\">Death in custody</div><div class=\"answer-line\">Death in the course of or as a result of a police operation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Consider need for scene /personal items and body preservation (all items</div><div class=\"answer-line\">entering the body plus devices attached to these must be preserved)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pronounce the death in the medical record</div><div class=\"answer-line\">Complete cause of Death certificate</div><div class=\"answer-line\">Consider whether a hospital autopsy is desirable</div><div class=\"answer-line\">Notify the family of the death</div><div class=\"answer-line\">Complete discharge summary</div><div class=\"answer-line\">Notify the GP</div><div class=\"answer-line\">Begin the death review process</div><div class=\"answer-line\">Consider tissue donation</div><div class=\"answer-line\">Source: Management of the Deceased -Practice Manual 2012, State Coroner’s Guidelines 2013</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"(Total Marks 12) A 29- year-old lady presents to ED on a Friday night, with bizarre behaviour following a recent admission under the medical team with cellulitis. She has a history of depression and self-harm. She is accompanied by her husband, who states that she has not slept since discharge. She is currently taking antibiotics and an SSRI. Her husband states that she started to hallucinate while she was an inpatient but didn’t mention it to medical staff as she wanted to go home. You are concerned that she has an acute presentation of psychosis.","parts":[{"id":"a","label":"Part A","prompt":"What features of her mental state exam indicate psychosis.\nList 4 features: (4 Marks)"},{"id":"b","label":"Part B","prompt":"Missed medical diagnoses in psychiatric patients are reported in up to 45% of patients. What are the main pitfalls in the “medical clearance process”.\nList 4 pitfalls:\n(2 Marks) She is calm and responsive to your assessment and request for further investigations. She is referred to the mental health team for review."},{"id":"c","label":"Part C","prompt":"What features of her presentation suggest she should remain for inpatient assessment?\nList 2 features:\n(2 Marks) She suddenly becomes more agitated in the department whilst waiting for the mental health team review. She is pacing in her cubicle and threatening harm to herself. Her husband has left the department."},{"id":"d","label":"Part D","prompt":"How do you manage this situation?\nList 4 steps\n(4 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Positive symptoms – Hallucinations, delusions, disorganised speech, disorganised behaviour, catatonic</div><div class=\"answer-line\">Negative symptoms – Blunted affect, emotional withdrawal, anhedonia, attention impairment.</div><div class=\"answer-line\">Functional decline</div><div class=\"answer-line\">Appearance</div><div class=\"answer-line\">Lack of insight</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">History – difficult to get from patient, failure to seek collateral, limited by location of review.</div><div class=\"answer-line\">Exam – Location of patient, failure to do full examination, no vitals or MMSE, no Neuro exam.</div><div class=\"answer-line\">Patient cooperation.</div><div class=\"answer-line\">Acceptance of “medical clearance” or over reliance on investigations, failure of ongoing review.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1st presentation</div><div class=\"answer-line\">History of depression and self harm – high risk of harm</div><div class=\"answer-line\">Carer fatigue</div><div class=\"answer-line\">Weekend therefore delay to follow up</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div><div class=\"answer-line\"><strong>The Prince Charles Hospita       The Royal Brisbane &amp;Women Hospital       Redcliffe  and Caboolture      Sunshine Coast U Hospital </strong></div><div class=\"answer-line\"><strong>  Emergency Department                  Emergency Departments        Emergency Departments</strong><strong> </strong></div><div class=\"answer-line\"><strong>     Emergency Department </strong></div><div class=\"answer-line\"><strong>How do you manage this situation?  </strong></div><div class=\"answer-line\"><strong>List 4 steps  </strong></div><div class=\"answer-line\"><strong>     (4 Marks) </strong></div><div class=\"answer-line\">Patient – verbal de-escalation</div><div class=\"answer-line\">Area – move to resus/monitored bed</div><div class=\"answer-line\">Staff – security, nursing</div><div class=\"answer-line\">Teams – include mental health</div><div class=\"answer-line\">Equipment – to provide safe chemical sedation or physical restraint</div><div class=\"answer-line\">Drugs – oral/iv/im options- with suggested doses</div><div class=\"answer-line\">Pass mark: 8/12</div><div class=\"answer-line\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</div><div class=\"answer-line\">Women Hospital Emergency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"(Total 18 marks) A 56-year-old female is brought in to your ED after a generalized tonic-clonic seizure. On your assessment, you note that there is right-sided weakness and history reveals frequent falls and headache in recent months. She has no significant past medical history and as part of the ED assessment, you have performed a CT brain, which is included in the Props booklet.\nThe patient is now GCS 15 and complaining of a headache. Her vital signs are as follows:\n\nTemp\n37.5C\n\nHR\n\nBP\n135 / 85\n\nRR\nO2 Sats 97%\nQuestions:","parts":[{"id":"a","label":"Part A","prompt":"List 3 pertinent findings on this CT.\n(3 Marks)"},{"id":"b","label":"Part B","prompt":"List 5 differential diagnoses for these radiological findings.\n(5 Marks)"},{"id":"c","label":"Part C","prompt":"List your management priorities in the Emergency Department (5 Marks)"},{"id":"d","label":"Part D","prompt":"State 5 important aspects to breaking bad news to this patient. (5 marks)\nGood luck Oh forgot, you still have the SCQ in the afternoon J"}],"propPages":["asset:imgcfa97e8d2e2431f711"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>13/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Large ring enhancing lesion to left frontoparietal hemisphere</td></tr><tr><td>•</td><td>Surrounding vasogenic oedema is evident</td></tr><tr><td>•</td><td>Mild mass effect with a minor degree of midline shift</td></tr><tr><td>•</td><td>Irregular thick margins with hyperattenuation (or heterogenous enhancement of the margin)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Primary malignancy (Glioblastoma Multiforme most likely, others include anaplastic astrocytoma)</td></tr><tr><td>•</td><td>Cerebral metastasis (Lung, Breast,</td></tr><tr><td>•</td><td>Cerebral abscess</td></tr><tr><td>•</td><td>Primary CNS lymphoma</td></tr><tr><td>•</td><td>Cerebral toxoplasmosis</td></tr><tr><td>•</td><td>Cerebral Tuberculosis</td></tr><tr><td>•</td><td>Subacute cerebral infarction</td></tr><tr><td>•</td><td>Tumefactive dymeylination</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Analgesia  with dose</td></tr><tr><td>•</td><td>Steroid Therapy (Must name drug and dose and route)</td></tr><tr><td colspan=\"2\">Dexamethasone 4-8mg stat then 4mg QID IV</td></tr><tr><td>•</td><td>Consultation with neurosurgery team for admission and further management</td></tr><tr><td>•</td><td>Seizure prophylaxis</td></tr><tr><td colspan=\"2\">Will accept either phenytoin load 15-20mg/kg or leviteracetam 20-30mg/kg</td></tr><tr><td>•</td><td>Social support for patient and family</td></tr><tr><td colspan=\"2\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</td></tr><tr><td colspan=\"2\">Women Hospital Emergency</td></tr><tr><td colspan=\"2\"><strong>The Prince Charles Hospita       The Royal Brisbane &amp;Women Hospital       Redcliffe  and Caboolture      Sunshine Coast U Hospital </strong></td></tr><tr><td colspan=\"2\"><strong>  Emergency Department                  Emergency Departments        Emergency Departments</strong><strong> </strong></td></tr><tr><td colspan=\"2\"><strong>     Emergency Department </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Any of the below</td></tr><tr><td>•</td><td>Appropriate setting: quiet area is desirable</td></tr><tr><td>•</td><td>Ask if she wants any family or NOK present</td></tr><tr><td>•</td><td>Having other support staff present: Senior RN or Social Worker</td></tr><tr><td>•</td><td>Use of a ‘Warning Shot’</td></tr><tr><td>•</td><td>Explain findings on the CT and the likely diagnoses in layman terms</td></tr><tr><td>•</td><td>Explain the next step in her treatment will be guided by the neurosurgical team</td></tr><tr><td>•</td><td>Use of silence for news to sink in</td></tr><tr><td>•</td><td>Offer tissue and water</td></tr><tr><td>•</td><td>Social worker to assist with any social issues</td></tr><tr><td>•</td><td>Answer any questions posed by patient and family</td></tr><tr><td colspan=\"2\">Will accept any combination of the above</td></tr><tr><td colspan=\"2\">Pass Mark is 13/18</td></tr><tr><td colspan=\"2\">without permission of the DEMT teams. property of The Prince Charles Hospital and The Royal Brisbane &amp;</td></tr><tr><td colspan=\"2\">Women Hospital Emergency</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
